SELECT td.TRAN_DATE, td.RECORD_SYS_DATE,     (td.RECORD_SYS_DATE - td.TRAN_DATE) AS days_late,     td.LOCATION, td.LOC_TYPE, td.ITEM, im.ITEM_DESC, td.DEPT, d.DEPT_NAME,     tdc.DECODE AS transaction_type, td.UNITS, td.TOTAL_COST, td.GL_REF_NO FROM MFCS_RDS.RDS_WV_TRAN_DATA td     JOIN MFCS_RDS.RDS_WV_ITEM_MASTER im ON td.ITEM = im.ITEM     LEFT JOIN MFCS_RDS.RDS_WV_TRAN_DATA_CODES tdc ON td.TRAN_CODE = tdc.CODE     LEFT JOIN MFCS_RDS.RDS_WV_DEPS d ON td.DEPT = d.DEPT WHERE (td.RECORD_SYS_DATE - td.TRAN_DATE) &gt; 7 AND   td.TRAN_DATE &gt;= ADD_MONTHS(SYSDATE,-3) ORDER BY days_late DESC, td.TRAN_DATE DESC</ds:dbquery><ds:target_type>Oracle 12c</ds:target_type><ds:object_name/></ds:dataptr><ds:columns><ds:column><ds:name>TRAN_DATE</ds:name><ds:datatype>timestamp</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>RECORD_SYS_DATE</ds:name><ds:datatype>timestamp</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>DAYS_LATE</ds:name><ds:datatype>number</ds:datatype></ds:column><ds:column><ds:name>LOCATION</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>LOC_TYPE</ds:name><ds:datatype>varchar(1)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>ITEM</ds:name><ds:datatype>varchar(25)</ds:datatype></ds:column><ds:column><ds:name>ITEM_DESC</ds:name><ds:datatype>varchar(250)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>DEPT</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>DEPT_NAME</ds:name><ds:datatype>varchar(120)</ds:datatype></ds:column><ds:column><ds:name>TRANSACTION_TYPE</ds:name><ds:datatype>varchar(250)</ds:datatype></ds:column><ds:column><ds:name>UNITS</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>TOTAL_COST</ds:name><ds:datatype>number</ds:datatype></ds:column><ds:column><ds:name>GL_REF_